vec3 palette(float t)
{
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.039,0.145,0.263);
    return a + b*sin(3.1415*(c*t + d));
}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
   vec2 uv0 = uv;
   vec2 uv1 = uv;
   vec3 finalcol = vec3(0.0);

   for (float i = 0.0; i < 2.0; i++)
   {
       uv = fract(uv*1.2) - 0.5;

       float d = length(uv * 0.5*exp(length(uv0*1.25))) + 0.3*exp(i*length(uv*uv0*i));
       uv1 = uv1*d*i*10.0;
       vec3 col = palette(1.2*length(uv0*1.1) +  iTime * 2.0);
       float d0 = sin(length(uv)*sin(d*3.0) + iTime*2.5)/3.0;
       d = sin(4.0*d*length(uv)*sin(d*3.0) + iTime*2.5)/3.0;
       d = 2.0*d;

       d = 0.15/(d-d0);

       finalcol += col*d;


   }

   fragColor = vec4(finalcol,  1.0);



}
